// Rasterize the existing brand assets once so every renderer uses the same portable RGBA pixels.
import {writeFileSync} from 'node:fs';
import sharp from 'sharp';

const logos = [
  ['SQUARE_LOGO', '../../../apps/docs/public/logo-square.svg', 64, 64],
  ['WIDE_LOGO', '../../../apps/docs/src/assets/logo.svg', 160, 64],
];
const output = [
  '// Generated by scripts/generate-fixture-logos.mjs. Do not edit by hand.',
  '// Regenerate with pnpm turbo run generate:fixture-logos --filter=@repo/core-testing.',
  '// cspell:disable',
];

for (const [name, source, width, height] of logos) {
  // A small palette keeps the checked-in pixels readable and independent of PNG decoders.
  const png = await sharp(new globalThis.URL(source, import.meta.url).pathname)
    .resize(width, height)
    .png({palette: true, colours: 16, dither: 0})
    .toBuffer();
  const data = await sharp(png).ensureAlpha().raw().toBuffer();
  const palette = [];
  const rows = [];
  for (let y = 0; y < height; y++) {
    let row = '';
    for (let x = 0; x < width; x++) {
      const offset = (y * width + x) * 4;
      const color = [...data.subarray(offset, offset + 4)];
      let index = palette.findIndex((entry) => entry.every((byte, i) => byte === color[i]));
      if (index === -1) index = palette.push(color) - 1;
      row += index.toString(16);
    }
    rows.push(row);
  }
  output.push(
    `export const ${name} = {`,
    `  width: ${width},`,
    `  height: ${height},`,
    '  palette: [',
    ...palette.map((color) => `    [${color.join(', ')}],`),
    '  ],',
    '  rows: [',
    ...rows.map((row) => `    '${row}',`),
    '  ],',
    '} as const;',
  );
}

writeFileSync(
  new globalThis.URL('../src/fixture-logo-images.ts', import.meta.url),
  `${output.join('\n')}\n`,
);
